package ai.taskforge.api; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestControllerAdvice public class ErrorHandler { @ExceptionHandler(ApiException.class) ResponseEntity<?> app(ApiException e){return ResponseEntity.badRequest().body(Map.of("success",false,"message",e.getMessage(),"errorCode",e.code,"timestamp",Instant.now()));} @ExceptionHandler(org.springframework.web.bind.MethodArgumentNotValidException.class) ResponseEntity<?> invalid(org.springframework.web.bind.MethodArgumentNotValidException e){return ResponseEntity.badRequest().body(Map.of("success",false,"message","One or more fields are invalid.","errorCode","VALIDATION_ERROR","timestamp",Instant.now()));} @ExceptionHandler(Exception.class) ResponseEntity<?> unknown(Exception e){return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body(Map.of("success",false,"message","The request could not be completed.","errorCode","INTERNAL_ERROR","timestamp",Instant.now()));} }
